WITH filtered AS (SELECT *, CASE WHEN merchant = 'Lazada' THEN 1 ELSE 0 END AS is_lazada, CAST(is_flagged AS INT) AS is_flagged_flag FROM transactions WHERE txn_time > TO_DATE('2023-07-21') AND txn_type IN ('CREDIT', 'FEE')) SELECT * FROM (SELECT account_id, txn_type, merchant, amount FROM filtered) src PIVOT (SUM(amount) FOR merchant IN ('Grab' AS grab, '7-Eleven' AS v_7_eleven, 'Shell' AS shell));
